alWeapons":{"value":"Commanding Culverins","desc":"Rogue Culverins equip weapons that deal 5x Damage to Overguard and Necramechs."},"ArbitersSyndicate":{"value":"Arbiters of Hexis"},"ArcadeAutomata":{"value":"Arcade Automate","desc":"Enemy guns launch large, slow moving orbs instead of their usual ordnance."},"Armorless":{"value":"Fractured Armor","desc":"Casting an ability reduces armor by 10% for 10s."},"ArtilleryBeacons":{"value":"Artillery Beacons","desc":"When killed, Scaldra troops drop artillery beacons that summon bombardments."},"AssassinsSyndicate":{"value":"Assassins"},"BalloonFest":{"value":"Balloonfest","desc":"Scaldra Harbingers are more numerous and attack and move more quickly."},"CephalonSudaSyndicate":{"value":"Cephalon Suda"},"CetusSyndicate":{"value":"Ostrons"},"ChemicalNoise":{"value":"Noise Suppression","desc":"Drones fly above Flare, spraying them with Efervon gas."},"CompetitionSpillover":{"value":"Competitive Streak","desc":"Random negative penalties from Amir and Aoi's \"Faceoff\" mode will be applied throughout the mission."},"ContactDamage":{"value":"Secondary Wounds","desc":"Gain 1 Puncture Status Effect every time you take damage."},"ContaminationZone":{"value":"Hold Your Breath","desc":"The entire region deals Toxin damage over time, increasing the longer players remain."},"DecayingFlesh":{"value":"Permanent Injury","desc":"Max health reduced each time health damage is taken"},"Deflectors":{"value":"Fortified Foes","desc":"Guardian Eximus units may be encountered, including Guardian Eximus Necramechs."},"DisruptiveSounds":{"value":"Vampire Rock","desc":"Flare creates a field that disrupts player abilities while draining energy to boost Flare's health. Flare slowly loses health when no players are in range."},"DoubleTrouble":{"value":"Double Trouble","desc":"Two Necramech Demolishers will attack any Conduit, but their health is reduced."},"DoubleTroubleLegacyte":{"value":"Mitosis","desc":"Two Legacytes spawn each round and twice as many