n"},"/lotus/weapons/tenno/shotgun/fullautoshotgun":{"value":"Boar"},"/lotus/weapons/tenno/shotgun/primeboar":{"value":"Boar Prime"},"/lotus/weapons/tenno/shotgun/quadshotgun":{"value":"Hek"},"/lotus/weapons/tenno/shotgun/shotgun":{"value":"Strun"},"/lotus/weapons/tenno/shotgun/shotgunvandal":{"value":"Strun Wraith"},"/lotus/weapons/tenno/throwingweapons/glasskunai/glasskunaiweapon":{"value":"Fusilai"},"/lotus/weapons/tenno/throwingweapons/kunai":{"value":"Kunai"},"/lotus/weapons/tenno/throwingweapons/lidagger/lidagger":{"value":"Spira"},"/lotus/weapons/tenno/throwingweapons/primelidagger/primelidagger":{"value":"Prime Li Dagger"},"/lotus/weapons/tenno/throwingweapons/primethrowingstar/primehikou":{"value":"Hikou Prime"},"/lotus/weapons/tenno/throwingweapons/stalkerkunai":{"value":"Despair"},"/lotus/weapons/tenno/throwingweapons/stickybomb/stickybombs":{"value":"Hikou"},"/lotus/weapons/tenno/throwingweapons/tennostars":{"value":"Tenno Stars"},"/lotus/weapons/tenno/throwingweapons/u18throwingknives/u18throwingknives":{"value":"Talons"},"/lotus/weapons/tenno/throwingweapons/variantsnowballs":{"value":"Variant Snow Balls"},"/lotus/weapons/tenno/throwingweapons/varianttennostars":{"value":"Variant Tenno Stars"},"/lotus/weapons/voidtrader/prismagrakata":{"value":"Prisma Grakata"},"/lotus/weapons/voidtrader/prismaskana":{"value":"Prisma Skana"},"/lotus/weapons/voidtrader/vtdetron":{"value":"Mara Detron"},"AbilityLockout":{"value":"Powerless","desc":"All Abilities are disabled until the squad kills 50 enemies."},"AcceleratedEnemies":{"value":"Bold Venture","desc":"Enemies deal -15% Damage and take +15% Damage but gain +15% Movement Speed, Attack Speed, and Fire Rate."},"AlchemicalShields":{"value":"Alchemical Invulnerability","desc":"10% of enemies are equipped with an impervious Elemental Barrier that can only be destroyed by an Amphor of the corresponding element."},"AntiGuard":{"value":"Dropped Guard","desc":"Warframe and ally Overguard gain reduced by 75%."},"AntiMaterialWeapons":{"value":"Commanding Culverins","desc":"Rogue Culverins equip weapons that deal 5x Damage to Overguard and Necramechs."},"ArbitersSyndicate":{"value":"Arbiters of Hexis"},"ArcadeAutomata":{"value":"Arcade Automate","desc":"Enemy guns launch large, slow moving orbs instead of their usual ordnance."},"Armorless":{"value":"Fractured Armor","desc":"Casting an ability reduces armor by 10% for 10s."},"ArtilleryBeacons":{"value":"Artillery Beacons","desc":"When killed, Scaldra troops drop artillery beacons that summon bombardments."},"AssassinsSyndicate":{"value":"Assassins"},"BalloonFest":{"value":"Balloonfest","desc":"Scaldra Harbingers are more numerous and attack and move more quickly."},"CephalonSudaSyndicate":{"value":"Cephalon Suda"},"CetusSyndicate":{"value":"Ostrons"},"ChemicalNoise":{"value":"Noise Suppression","desc":"Drones fly above Flare, spraying them with Efervon gas."},"CompetitionSpillover":{"value":"Competitive Streak","desc":"Random negative penalties from Amir and Aoi's \"Faceoff\" mode will be applied throughout the mission."},"ContactDamage":{"value":"Secondary Wounds","desc":"Gain 1 Puncture Status Effect every time you take damage."},"ContaminationZone":{"value":"Hold Your Breath","desc":"The entire region deals Toxin damage over time, increasing the longer players remain."},"DecayingFlesh":{"value":"Permanent Injury","desc":"Max health reduced each time health damage is taken"},"Deflectors":{"value":"Fortified Foes","desc":"Guardian Eximus units may be encountered, including Guardian Eximus Necramechs."},"DisruptiveSounds":{"value":"Vampire Rock","desc":"Flare creates a field that disrupts player abilities while draining energy to boost Flare's health. Flare slowly loses health when no players are in range."},"DoubleTrouble":{"value":"Double Trouble","desc":"Two Necramech Demolishers will attack any Conduit, but their health is reduced."},"DoubleTroubleLegacyte":{"value":"Mitosis","desc":"Two Legacytes spawn each round and twice as many captures are needed for success."},"DrainingResiduals":{"value":"Devil's Bargain","desc":"Allies within 4m of slain enemies gain 25% Fire Rate at the cost of -50% Ammo Efficiency."},"DullBlades":{"value":"Dull Blades","desc":"-50% melee combo chance"},"EMPBlackHole":{"value":"Alluring Arcocanids","desc":"As Rogue Arcocanids charge attacks, they pull Warframes towards them."},"EfervonFog":{"value":"Dense Fog","desc":"Efervon gas blankets the level. Enemies may drop filters that can provide a temporary reprieve."},"EnergyStarved":{"value":"Energy Exhaustion","desc":"Lose 2 Energy per second for each enemy within 10 meters of you."},"EntratiSyndicate":{"value":"Entrati"},"EscalateImmediately":{"value":"Cache Crash","desc":"Consequences of opening a Supply Cache are active from the start and will intensify if the Supply Cache is opened. Failure to open a Supply Cache doubles the kill count required to finish the mission."},"EventSyndicate":{"value":"Operations Syndicate"},"Exhaustion":{"value":"Energy Exhaustion","desc":"Lose 2 Energy per second for each enemy within 10 meters of you."},"EximusGrenadiers":{"value":"Eximus Amphors","desc":"Eximus units always drop Amphors."},"ExplosiveCrawlers":{"value":"Explosive Potential","desc":"Rupturing Fragments replace Shuffling Fragments."},"ExplosiveEnergy":{"value":"Miasmite Mash","desc":"Enemies drop Miasmites upon death that immediately rush Flare."},"FactionSwarm_Scaldra":{"value":"Scaldra Speed Run","desc":"All enemies are replaced with Scaldra and move much faster."},"FactionSwarm_Techrot":{"value":"Techrot Speed Run","desc":"All enemies are replaced with Techrot and move much faster."},"FallFog":{"value":"Foggy Fall","desc":"A fog limits vision across the mission zone."},"FortifiedFoes":{"value":"Sealed Armor","desc":"Enemies take 90% less damage from non-Weak Point hits."},"FragileNodes":{"value":"Unified Purpose","desc":"Enemies can target and destroy Conduits."},"Framecurse":{"value":"Framecurse syndrome","desc":"Activating an Ability inflicts 50 damage upon you."},"Gearless":{"value":"Gear Embargo","desc":"Gear cannot be used."},"GestatingTumors":{"value":"Sporogenesis","desc":"Techrot Tumors appear near Hell-Scrubbers, increasing the rate of life support decay with each active tumor."},"GrowingIncursion":{"value":"Fissure Cascade","desc":"Fissures rip into the mission, causing the Enemy Level to go up by 1 every 10s. Destroy them to stop the level from increasing further."},"HarshWords":{"value":"Barbed Glyphs","desc":"Each Glyph inflicts a small amount of damage when collected."},"HeavyWarfare":{"value":"Heavy Warfare","desc":"Enemies take 95% less damage from non-heavy weapons. Enemies will drop heavy ammo packs and heavy weapon recall time reduced to 5s."},"HighScalingLegacyte":{"value":"Growth Hormones","desc":"Legacytes are more powerful with each generation but take longer to escape."},"HostileOvergrowth":{"value":"It's Alive","desc":"Within the underground, hostile overgrowths will attack if players stops moving."},"HostileSecurity":{"value":"Eroding Senses","desc":"The Auricle and Vitreum take damage over time, collecting the required Vosphene Glyphs will halt the degradation and partially heal them."},"InfectedTechrot":{"value":"Corrupted Flesh","desc":"Techrot enemies are infused with Efervon and take damage over time. They explode when killed and leave behind deadly Efervon in their wake."},"InfiniteTide":{"value":"Relentless Tide","desc":"The Fragmented Tide never stops attacking."},"JadeSpring":{"value":"Jade Spirits","desc":"Jade Wisps haunt the region. If approached, they chase down the player responsible and transform into Jade Light beams."},"KahlSyndicate":{"value":"Kahl's Garrison"},"Knifestep":{"value":"Knifestep Syndrome","desc":"Lose 2 Health when moving. Jumping pauses the effect."},"LostInTranslation":{"value":"Glyph Inflation","desc":"The security system requires twice as many Vosphene Glyphs to activate."},"MiasmiteHive":{"value":"Miasmite Swarm","de